package com.gnostica.modules.settings.controller;
import com.gnostica.core.dto.response.ApiResponse; import com.gnostica.modules.settings.dto.response.*; import com.gnostica.modules.settings.service.TermService; import jakarta.servlet.http.HttpServletRequest; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/public/terms") @RequiredArgsConstructor public class PublicTermsController { private final TermService service; @GetMapping("/menu") public ApiResponse<List<TermModuleResponse>> menu(){return ApiResponse.success(service.publicTree());} @GetMapping("/**") public ApiResponse<TermResponse> term(HttpServletRequest r){return ApiResponse.success(service.publicTerm(r.getRequestURI().replaceFirst(".*/api/public/terms/", "")));} }
